package live.linghe.privateinput;
import android.app.*;import android.content.*;import android.os.*;import java.io.*;import java.net.*;import java.util.*;import org.json.*;
/** Fresh test-UID contexts only. Never addresses the main application's files. */
public final class IndependentSyncCheck extends Instrumentation {
  Bundle args;int checks;Context base;String nonce;File root;ArrayList<SyncStore> keys=new ArrayList<>();
  @Override public void onCreate(Bundle b){super.onCreate(b);args=b;start();}
  void require(boolean b,String label){if(!b)throw new AssertionError(label);checks++;try{write("independent-progress.json",new JSONObject().put("check",checks).put("phase",label));}catch(Exception ignored){}}
  Context node(String name){File folder=new File(root,name);File files=new File(folder,"files"),cache=new File(folder,"cache");files.mkdirs();cache.mkdirs();return new ContextWrapper(base){public Context getApplicationContext(){return this;}public File getFilesDir(){return files;}public File getCacheDir(){return cache;}public android.content.SharedPreferences getSharedPreferences(String key,int mode){return base.getSharedPreferences("independent-"+nonce+"-"+name+"-"+key,mode);}};}
  SyncClient client(Context c,String name)throws Exception {SyncStore s=new SyncStore(c,"live.linghe.privateinput.tests.independent."+nonce+"."+name);keys.add(s);return new SyncClient(c,s);}
  void write(String name,JSONObject value)throws Exception {try(FileOutputStream out=new FileOutputStream(new File(base.getExternalFilesDir(null),name))){out.write(SyncCrypto.bytes(value.toString()));}}
  JSONObject waitFile(String name,long timeout)throws Exception {long deadline=System.currentTimeMillis()+timeout;File file=new File(base.getExternalFilesDir(null),name);while(System.currentTimeMillis()<deadline){if(file.isFile())return LosslessJson.object(SyncCrypto.utf8(java.nio.file.Files.readAllBytes(file.toPath())),2*1024*1024);Thread.sleep(250);}throw new IOException("fixture handoff timed out: "+name);}
  @Override public void onStart(){Bundle result=new Bundle();try{
    base=getTargetContext();startActivitySync(new Intent(base,SyncAcceptanceActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread tested=Thread.currentThread();Thread watchdog=new Thread(()->{for(int k=0;k<120;k++){try{Thread.sleep(2000);StringBuilder trace=new StringBuilder();trace.append("checks=").append(checks).append(" state=").append(tested.getState()).append("\n");for(StackTraceElement frame:tested.getStackTrace())trace.append(frame).append("\n");try(FileOutputStream out=new FileOutputStream(new File(base.getExternalFilesDir(null),"independent-stack.txt"))){out.write(SyncCrypto.bytes(trace.toString()));}}catch(Exception ignored){}}},"independent-scoped-watchdog");watchdog.setDaemon(true);watchdog.start();require(base.getPackageName().equals("live.linghe.privateinput.tests"),"self target only");nonce=UUID.randomUUID().toString();root=new File(base.getFilesDir(),"independent-"+nonce);root.mkdirs();
    JSONObject swift=LosslessJson.object(SyncCrypto.utf8(java.nio.file.Files.readAllBytes(new File(args.getString("fixture")).toPath())),2*1024*1024);
    JSONObject latest=swift.getJSONObject("second").getJSONObject("membership");SyncCrypto.verifyMembership(latest,SyncCrypto.anchor(swift.getJSONObject("genesis")),swift.getJSONObject("old"));require(latest.getInt("version")==2,"Apple signed lineage verifies on vivo");
    String qrText=new String(java.nio.file.Files.readAllBytes(new File(args.getString("qr")).toPath()),SyncCrypto.UTF8);JSONObject qr=SyncCrypto.decodeQRQuery(new URI(qrText).getRawQuery().substring(5));require(qr.getJSONObject("invitation").getString("endpoint").equals("https://private.example.invalid"),"Apple QR envelope decrypts on vivo");
    Context original=node("original"),third=node("third"),fourth=node("fourth");SyncClient owner=client(original,"original"),survivor=client(third,"third"),newcomer=client(fourth,"fourth");
    owner.createGroup(args.getString("endpoint"));owner.synchronize();JSONObject ticket=owner.invite();String realGroup=SyncCrypto.decodeQRQuery(new URI(ticket.getString("link")).getRawQuery().substring(5)).getJSONObject("invitation").getJSONObject("anchor").getString("group");write("independent-original-ticket.json",ticket);
    long deadline=System.currentTimeMillis()+80000;while(owner.members()<2&&System.currentTimeMillis()<deadline){owner.synchronize();Thread.sleep(1000);}require(owner.members()==2,"original admitted Apple peer");
    // No further original-device work after this point.
    JSONObject apple=waitFile("independent-apple-ticket.json",80000);survivor.joinQR(apple.getString("link"));deadline=System.currentTimeMillis()+80000;
    while(!survivor.connected()&&System.currentTimeMillis()<deadline){survivor.synchronize();write("independent-join-diagnostic.json",new JSONObject().put("connected",survivor.connected()).put("joining",survivor.joining()).put("waiting",survivor.pairingWaitReason()));Thread.sleep(1000);}require(survivor.connected()&&survivor.members()==3,"Apple nonowner independently admitted vivo");survivor.synchronize();
    require(survivor.devices().length()==3,"complete device list");survivor.consent(false,true);require(survivor.clipboard(),"clipboard consent set");survivor.sendText("independent-node synthetic message");require(true,"encrypted message submitted");survivor.synchronize();
    waitFile("independent-apple-received.json",50000);boolean blocked=false;String originalID=null,macID=null;
    JSONArray devices=survivor.devices();for(int i=0;i<devices.length();i++){JSONObject row=devices.getJSONObject(i);if(row.optString("kind").equals("macos"))macID=row.getString("device");else if(!row.optBoolean("isSelf"))originalID=row.getString("device");}
    try{survivor.revoke(originalID);}catch(Exception expected){blocked=true;}require(blocked,"phone cannot remove another phone");require(macID!=null,"Apple peer has desktop profile");survivor.revoke(macID);waitFile("independent-apple-departed.json",50000);require(survivor.members()==2,"phone removed desktop with atomic rotation");
    JSONObject next=survivor.invite();newcomer.joinQR(next.getString("link"));deadline=System.currentTimeMillis()+70000;
    while(!newcomer.connected()&&System.currentTimeMillis()<deadline){survivor.synchronize();newcomer.synchronize();Thread.sleep(1000);}require(newcomer.connected()&&newcomer.members()==3,"vivo survives original and Apple peer absence to admit another node");newcomer.synchronize();
    boolean range=false;try{newcomer.setIdleDays(91);}catch(Exception expected){range=true;}require(range,"90 day bound");newcomer.setIdleDays(1);
    File personal=new File(fourth.getFilesDir(),"nine-choice-memory-v3.json");try(FileOutputStream out=new FileOutputStream(personal)){out.write(SyncCrypto.bytes("synthetic-private-choice"));}
    File backup=new File(fourth.getFilesDir(),"learning-checkpoint-v1.json.bak"),staged=new File(fourth.getFilesDir(),"nine-choice-memory-v3.json.new");for(File file:new File[]{backup,staged})try(FileOutputStream out=new FileOutputStream(file)){out.write(SyncCrypto.bytes("synthetic-private-backup"));}
    File shared=new File(fourth.getFilesDir(),"Shared");shared.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(shared,"personal-lexicon-v1.json"))){out.write(SyncCrypto.bytes("synthetic-private-phrase"));}
    fourth.getSharedPreferences("sync-consent",0).edit().putLong("expires",System.currentTimeMillis()/1000-1).commit();
    SyncClient reset=new SyncClient(fourth,keys.get(2));require(!reset.connected(),"local expiry leaves group");require(!personal.exists()&&!new File(shared,"personal-lexicon-v1.json").exists(),"local expiry removes personalized data");require(!backup.exists()&&!staged.exists(),"atomic backup and interrupted write cannot resurrect personal data");require(!new String(java.nio.file.Files.readAllBytes(new File(fourth.getFilesDir(),"Sync/state-v1.enc").toPath()),SyncCrypto.UTF8).contains("synthetic-private"),"remaining state has no personal plaintext");
    write("independent-result.json",new JSONObject().put("passed",true).put("checks",checks).put("group",realGroup).put("fixtureNonce",nonce));result.putString("result","Passed");result.putInt("checks",checks);finish(-1,result);
  }catch(Throwable error){result.putString("result","Failed");result.putString("error",error.toString());finish(0,result);}}
}
